import { lazy, FC, Suspense } from 'react';
import { Route, Routes, Navigate } from 'react-router-dom';
import { MasterLayout } from '../../_metronic/layout/MasterLayout';
import TopBarProgress from 'react-topbar-progress-indicator';
import { DashboardWrapper } from '../pages/dashboard/DashboardWrapper';
import { MenuTestPage } from '../pages/MenuTestPage';
import { getCSSVariableValue } from '../../_metronic/assets/ts/_utils';
import { WithChildren } from '../../_metronic/helpers';
import BuilderPageWrapper from '../pages/layout-builder/BuilderPageWrapper';

const AdminRoutes = () => {
  const ExampleRoutes = lazy(() => import('../modules/example/ExampleRoutes'));
  const SettingRoutes = lazy(() => import('../modules/setting/SettingRoutes'));
  const SetupRoutes = lazy(() => import('../modules/setup/SetupRoutes'));
  const InventoryRoutes = lazy(
    () => import('../modules/inventory/InventoryRoutes')
  );
  const PatientRoutes = lazy(() => import('../modules/patient/PatientRoutes'));
  const AppointmentRoutes = lazy(() => import('../modules/appointment/AppointmentRoutes'));
  const OpdRoutes = lazy(() => import('../modules/opd/OpdRoutes'));
  const DoctorRoutes = lazy(() => import('../modules/doctor/DoctorRoutes'));
  const IpdRoutes = lazy(() => import('../modules/ipd/IpdRoutes'));
  const EmergencyRoutes = lazy(() => import('../modules/emergency/EmergencyRoutes'));
  const LabRoutes = lazy(() => import('../modules/lab/LabRoutes'));
  const RadiologyRoutes = lazy(() => import('../modules/radiology/RadiologyRoutes'));
  const InsuranceRoutes = lazy(() => import('../modules/insurance/InsuranceRoutes'));
  const BillingRoutes = lazy(() => import('../modules/billing/BillingRoutes'));
  const ReportRoutes = lazy(() => import('../modules/reports/components/ReportRoutes'));
  const OtRoutes = lazy(() => import('../modules/ot/OtRoutes'));
  const HrRoutes = lazy(() => import('../modules/hr/HrRoutes'));
  const BloodBankRoutes = lazy(() => import('../modules/bloodbank/BloodBankRoutes'));

  return (
    <Routes>
      <Route element={<MasterLayout />}>
        {/* CUSTOM MENU ROUTES */}
        {/* <Route path={'example'} element={<ExampleUserListController />} /> */}
        <Route
          path={'/example/*'}
          element={
            <SuspensedView>
              <ExampleRoutes />
            </SuspensedView>
          }
        />
        <Route
          path={'/setting/*'}
          element={
            <SuspensedView>
              <SettingRoutes />
            </SuspensedView>
          }
        />
        <Route
          path={'/setup/*'}
          element={
            <SuspensedView>
              <SetupRoutes />
            </SuspensedView>
          }
        />
        <Route
          path={'/inventory/*'}
          element={
            <SuspensedView>
              <InventoryRoutes />
            </SuspensedView>
          }
        />
        <Route
          path={'/patient/*'}
          element={
            <SuspensedView>
              <PatientRoutes />
            </SuspensedView>
          }
        />
        <Route
          path={'/appointment/*'}
          element={
            <SuspensedView>
              <AppointmentRoutes />
            </SuspensedView>
          }
        />
        <Route
          path={'/opd/*'}
          element={
            <SuspensedView>
              <OpdRoutes />
            </SuspensedView>
          }
        />
        <Route
          path={'/doctor/*'}
          element={
            <SuspensedView>
              <DoctorRoutes />
            </SuspensedView>
          }
        />
        <Route
          path={'/ipd/*'}
          element={
            <SuspensedView>
              <IpdRoutes />
            </SuspensedView>
          }
        />
        <Route
          path={'/emergency/*'}
          element={
            <SuspensedView>
              <EmergencyRoutes />
            </SuspensedView>
          }
        />
        <Route
          path={'/lab/*'}
          element={
            <SuspensedView>
              <LabRoutes />
            </SuspensedView>
          }
        />
        <Route
          path={'/radiology/*'}
          element={
            <SuspensedView>
              <RadiologyRoutes />
            </SuspensedView>
          }
        />
        <Route
          path={'/insurance/*'}
          element={
            <SuspensedView>
              <InsuranceRoutes />
            </SuspensedView>
          }
        />
        <Route
          path={'/billing/*'}
          element={
            <SuspensedView>
              <BillingRoutes />
            </SuspensedView>
          }
        />
        <Route
          path={'/report/*'}
          element={
            <SuspensedView>
              <ReportRoutes />
            </SuspensedView>
          }
        />
        <Route
          path={'/ot/*'}
          element={
            <SuspensedView>
              <OtRoutes />
            </SuspensedView>
          }
        />
        <Route
          path={'/hr/*'}
          element={
            <SuspensedView>
              <HrRoutes />
            </SuspensedView>
          }
        />
        <Route
          path={'/blood-bank/*'}
          element={
            <SuspensedView>
              <BloodBankRoutes />
            </SuspensedView>
          }
        />

        {/* Redirect to Dashboard after success login/registartion */}
        <Route path="auth/*" element={<Navigate to="/admin/dashboard" />} />
        {/* Pages */}
        <Route path="/dashboard" element={<DashboardWrapper />} />
        <Route path="builder" element={<BuilderPageWrapper />} />
        <Route path="menu-test" element={<MenuTestPage />} />
        {/* Lazy Modules */}
        {/* Page Not Found */}
        <Route path="*" element={<Navigate to="/error/404" />} />
      </Route>
    </Routes>
  );
};

const SuspensedView: FC<WithChildren> = ({ children }) => {
  const baseColor = getCSSVariableValue('--bs-primary');
  TopBarProgress.config({
    barColors: {
      '0': baseColor,
    },
    barThickness: 1,
    shadowBlur: 5,
  });
  return <Suspense fallback={<TopBarProgress />}>{children}</Suspense>;
};

export { AdminRoutes };
