import {AxiosPromise} from 'axios'
import {CONSTANT_CONFIG} from '../../constants'
import {HttpService} from '../../services/http.services'

const RESOURCE_ENDPOINT = `${CONSTANT_CONFIG.SERVER_PREFIX}/analyzer-interface`

export default class AnalyzerInterfaceApi {
  public messages = (params = {}): AxiosPromise<any> => HttpService.get(`${RESOURCE_ENDPOINT}/messages`, params)
  public import = (payload = {}): AxiosPromise<any> => HttpService.post(`${RESOURCE_ENDPOINT}/import`, payload)
}
